<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Profile\Infrastructure\Driver\Html\Panels;

class AccountDeletionPanel
{
    public function renderRequest(string $deleteUrl, string $cancelUrl, ?string $error, array $t = []): string
    {
        $errorHtml = $error !== null && $error !== ''
            ? '<p class="error-message">' . htmlspecialchars($error) . '</p>'
            : '';
        $title = htmlspecialchars($t['title'] ?? 'Delete account');
        $help = $t['help'] ?? 'This action is permanent and cannot be undone.';
        $requestLabel = htmlspecialchars($t['request'] ?? 'Request deletion');
        $backLabel = htmlspecialchars($t['backToProfile'] ?? 'Back to profile');
        $deleteUrl = htmlspecialchars($deleteUrl);
        $cancelUrl = htmlspecialchars($cancelUrl);

        return '<h1>' . $title . '</h1>'
            . '<p class="warning-text">' . $help . '</p>'
            . $errorHtml
            . '<form method="POST" action="' . $deleteUrl . '" class="profile-actions">'
            . '<input type="hidden" name="confirm" value="yes" />'
            . '<input type="submit" class="danger-button" value="' . $requestLabel . '" />'
            . '<a class="secondary-button" href="' . $cancelUrl . '">' . $backLabel . '</a>'
            . '</form>';
    }

    public function renderSent(string $cancelUrl, array $t = []): string
    {
        $title = htmlspecialchars($t['sentTitle'] ?? 'Deletion requested');
        $help = htmlspecialchars($t['sentHelp'] ?? 'Your deletion request has been received. You will receive a confirmation email.');
        $backLabel = htmlspecialchars($t['backToProfile'] ?? 'Back to profile');
        $cancelUrl = htmlspecialchars($cancelUrl);

        return '<h1>' . $title . '</h1>'
            . '<p class="change-password-success">' . $help . '</p>'
            . '<div class="profile-actions">'
            . '<a class="secondary-button" href="' . $cancelUrl . '">' . $backLabel . '</a>'
            . '</div>';
    }

    public function renderConfirmed(array $t = []): string
    {
        $title = htmlspecialchars($t['confirmedTitle'] ?? 'Account deleted');
        $help = htmlspecialchars($t['confirmedHelp'] ?? 'Your account has been permanently deleted.');

        return '<h1>' . $title . '</h1>'
            . '<p class="change-password-success">' . $help . '</p>';
    }

    public function renderTokenError(string $cancelUrl, array $t = []): string
    {
        $title = htmlspecialchars($t['title'] ?? 'Delete account');
        $error = htmlspecialchars($t['errorToken'] ?? 'The deletion link is invalid or has expired.');
        $backLabel = htmlspecialchars($t['backToProfile'] ?? 'Back to profile');
        $cancelUrl = htmlspecialchars($cancelUrl);

        return '<h1>' . $title . '</h1>'
            . '<p class="error-message">' . $error . '</p>'
            . '<div class="profile-actions">'
            . '<a class="secondary-button" href="' . $cancelUrl . '">' . $backLabel . '</a>'
            . '</div>';
    }
}
